-- run AFTER all data parts are loaded (faster than loading with indexes)
ALTER TABLE ONLY public.etf_symbols ADD CONSTRAINT etf_symbols_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.symbols_symbolintraday ADD CONSTRAINT symbols_symbolintraday_pkey PRIMARY KEY (id);
CREATE INDEX symbols_symbolintraday_report_time ON public.symbols_symbolintraday USING btree (report_time);
CREATE INDEX symbols_symbolintraday_symbol_id ON public.symbols_symbolintraday USING btree (symbol_id);
CREATE INDEX symbols_symbolintraday_nav_time ON public.symbols_symbolintraday USING btree (nav_time);
ANALYZE public.etf_symbols; ANALYZE public.symbols_symbolintraday;
